import sys
from typing import List

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        answer = [0] * len(queries)

        def update(index, color):
            if nums[index] == color:
                return 0

            prev = index - 1
            next_ = index + 1

            current_count = 0
            if prev >= 0 and nums[prev] == nums[index]:
                current_count += 1
            if next_ < n and nums[next_] == nums[index]:
                current_count += 1

            nums[index] = color

            new_count = 0
            if prev >= 0 and nums[prev] == nums[index]:
                new_count += 1
            if next_ < n and nums[next_] == nums[index]:
                new_count += 1

            return new_count - current_count

        for i, (index, color) in enumerate(queries):
            answer[i] = update(index, color)

        return answer

