class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)
        one_index = nums.index(1)
        n_index = nums.index(n)

        # If 1 is already at the beginning and n is at the end, no swaps are needed
        if one_index == 0 and n_index == n - 1:
            return 0

        # If 1 is at the end, we need to move it to the beginning
        if one_index == n - 1:
            return n - 2 - n_index

        # If n is at the beginning, we need to move it to the end
        if n_index == 0:
            return one_index + n - 1

        # Calculate the minimum number of swaps needed
        swaps = one_index + (n - 1 - n_index)
        if one_index > n_index:
            swaps -= 1

        return swaps

class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        max_length = 0
        left = 0
        consecutive_pairs = 0

        for right in range(n):
            if right > 0 and s[right] == s[right - 1]:
                consecutive_pairs += 1

            while consecutive_pairs > 1:
                if right > 0 and s[right] == s[right - 1]:
                    consecutive_pairs -= 1
                left += 1

            max_length = max(max_length, right - left + 1)

        return max_length

